#include "qmc.hpp"
#include "chk.hpp"
#include <random>
#include <set>
#include <vector>
using namespace mc;
static double se_mean(std::vector<double> x, double& mean) { double m = 0, v = 0, n = x.size(); for (double a : x) m += a / n; for (double a : x) v += (a - m) * (a - m) / (n - 1); mean = m; return std::sqrt(v / n); }
int main() {
    sec("first_points", [] { Sobol s(3); double p[3]; double want[6][3] = {{0, 0, 0}, {.5, .5, .5}, {.75, .25, .25}, {.25, .75, .75}, {.375, .375, .625}, {.875, .875, .125}};
        for (auto& w : want) { s.next(p); for (int d = 0; d < 3; d++) if (!near(p[d], w[d], 1e-12)) return false; } return true; });
    sec("stratified_1d", [] { for (int d : {1, 2, 5, 16, 32}) { Sobol s(d); std::vector<double> p(d); std::vector<int> c(1024, 0); for (int i = 0; i < 1024; i++) { s.next(p.data()); c[int(p[d - 1] * 1024)]++; } for (int x : c) if (x != 1) return false; } return true; });
    sec("stratified_2d", [] { Sobol s(2); double p[2]; std::vector<int> c(256, 0); for (int i = 0; i < 256; i++) { s.next(p); c[int(p[0] * 4) * 16 + int(p[1] * 16)]++; } for (int i = 0; i < 64; i++) if (c[(i / 16) * 16 + i % 16] < 0) return false; int bad = 0; std::vector<int> e(256, 0); Sobol t(2); for (int i = 0; i < 256; i++) { t.next(p); e[int(p[0] * 16) * 16 + int(p[1] * 16)]++; } for (int x : e) if (x != 1) bad++; fprintf(stderr, "bad %d\n", bad); return bad == 0; });
    sec("all_dims_valid", [] { Sobol s(32); std::vector<double> p(32); for (int i = 0; i < 100000; i++) { s.next(p.data()); for (double x : p) if (!(x >= 0 && x < 1)) return false; } return true; });
    sec("bridge_endpoint", [] { std::vector<double> z(16, 0.0), w(16); z[0] = 1.5; brownian_bridge(z.data(), 16, 4.0, w.data()); return near(w[15], 1.5 * 2, 1e-12) && near(w[7], 1.5, 1e-12) && near(w[3], .75, 1e-12); });
    sec("bridge_covariance", [] { std::mt19937_64 g(1); std::normal_distribution<double> n; int d = 8, N = 2000000; std::vector<double> z(d), w(d), c(d * d, 0.0); for (int i = 0; i < N; i++) { for (auto& a : z) a = n(g); brownian_bridge(z.data(), d, 2.0, w.data()); for (int a = 0; a < d; a++) for (int b = 0; b < d; b++) c[a * d + b] += w[a] * w[b]; } for (int a = 0; a < d; a++) for (int b = 0; b < d; b++) if (!near(c[a * d + b] / N, std::min(a + 1, b + 1) * .25, .01)) return false; return true; }, 60);
    sec("bridge_is_a_bijection", [] { std::vector<double> z(8), w(8), u(8); for (int k = 0; k < 8; k++) { std::fill(z.begin(), z.end(), 0.0); z[k] = 1; brownian_bridge(z.data(), 8, 1, w.data()); double m = 0; for (double a : w) m = std::max(m, std::fabs(a)); if (m == 0) return false; } std::fill(z.begin(), z.end(), .0); brownian_bridge(z.data(), 8, 1, w.data()); for (double a : w) if (a != 0) return false; return true; });
    sec("digital_shift_unbiased", [] { double ref = 0; { std::mt19937_64 g(9); std::normal_distribution<double> n; double S0 = 100, K = 100, r = .03, s = .2, T = 1; int f = 16; long N = 8000000; double dt = T / f, sum = 0; for (long i = 0; i < N; i++) { double x = std::log(S0), avg = 0; for (int k = 0; k < f; k++) { x += (r - .5 * s * s) * dt + s * std::sqrt(dt) * n(g); avg += std::exp(x); } sum += std::max(avg / f - K, 0.0); } ref = std::exp(-r * T) * sum / N; }
        auto a = asian_rqmc(100, 100, .03, .2, 1, 16, 1 << 14, 32, 3, true); auto b = asian_rqmc(100, 100, .03, .2, 1, 16, 1 << 14, 32, 3, false); return near(a.price, ref, 5 * a.std_error + .006) && near(b.price, ref, 5 * b.std_error + .006) && a.std_error > 0; }, 200);
    sec("qmc_beats_pseudo", [] { auto a = asian_rqmc(100, 100, .03, .2, 1, 16, 1 << 14, 32, 4, true); std::mt19937_64 g(2); std::normal_distribution<double> n; std::vector<double> x; double S0 = 100, K = 100, r = .03, s = .2, T = 1; int f = 16, N = (1 << 14) * 32; double dt = T / f; std::vector<double> payoff; for (int i = 0; i < 32; i++) { double sum = 0; for (int p = 0; p < N / 32; p++) { double y = std::log(S0), avg = 0; for (int k = 0; k < f; k++) { y += (r - .5 * s * s) * dt + s * std::sqrt(dt) * n(g); avg += std::exp(y); } sum += std::max(avg / f - K, 0.0); } x.push_back(std::exp(-r * T) * sum / (N / 32)); } double m; double se = se_mean(x, m); fprintf(stderr, "rqmc %.5f pseudo %.5f\n", a.std_error, se); return a.std_error < se / 8; }, 100);
    sec("bridge_beats_forward", [] { double b = 0, c = 0; for (int s = 0; s < 3; s++) { b += asian_rqmc(100, 100, .03, .2, 1, 32, 1 << 12, 32, 50 + s, true).std_error; c += asian_rqmc(100, 100, .03, .2, 1, 32, 1 << 12, 32, 50 + s, false).std_error; } fprintf(stderr, "bb %.5f fw %.5f\n", b, c); return b < c * .75; }, 100);
    return 0;
}
